const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization;
if (!authHeader || typeof authHeader !== 'string') { throw new Error('Unauthorized'); }
const parts = authHeader.split(' ');
if (parts.length < 2 || !parts[1]) { throw new Error('Unauthorized'); }
const tokenParts = parts[1].split('.');
if (tokenParts.length < 2) { throw new Error('Unauthorized'); }
const base64 = tokenParts[1].replace(/-/g, '+').replace(/_/g, '/');
const payload = JSON.parse(Buffer.from(base64, 'base64').toString('utf8'));
const body = $input.first().json.body || {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const bookId = UUID_RE.test(String(body.book_id || '')) ? String(body.book_id) : null;
const status = body.status === 'ready' ? 'ready' : (body.status === 'failed' ? 'failed' : null);
let err = null;
if (!bookId) err = 'معرّف الكتاب غير صالح';
else if (!status) err = 'حالة غير صالحة';

const posInt = (v) => { const n = Number(v); return Number.isInteger(n) && n > 0 && n < 10000000 ? String(n) : ''; };
const chapters = (Array.isArray(body.chapters) ? body.chapters : []).slice(0, 500).map(c => ({
  title: String((c && c.title) || '').slice(0, 200),
  page: Number.isInteger(Number(c && c.page)) && Number(c.page) > 0 ? Number(c.page) : null,
  level: Number.isInteger(Number(c && c.level)) && Number(c.level) > 0 ? Number(c.level) : 1
})).filter(c => c.title);

return {
  teacherId: payload.sub,
  bookId,
  status,
  errorMessage: String(body.error_message || '').slice(0, 500),
  pageCount: posInt(body.page_count),
  chapterCount: String(chapters.length),
  chaptersJson: chapters.length ? JSON.stringify(chapters) : '',
  isScanned: body.is_scanned === true ? 'true' : 'false',
  ocrPages: String(Math.max(0, Math.min(100000, parseInt(body.ocr_page_count, 10) || 0))),
  isValid: err === null,
  validationError: err
};
